from __future__ import annotations

from fastapi.responses import HTMLResponse


def dashboard_page() -> HTMLResponse:
    return HTMLResponse(
        """<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
</style><style>.queue-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.queue-tools{display:flex;gap:8px;align-items:center}.queue-tools select{font:inherit;border:1px solid #cbdad3;border-radius:8px;padding:8px;background:#fff}.case-list{display:grid;gap:7px;margin-top:12px}.case-row{display:flex;justify-content:space-between;gap:12px;padding:10px 12px;border:1px solid #e0e9e4;border-radius:9px;font-size:13px}.case-row strong{color:#183f34}.review-fields{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:12px 0}.review-fields label{font-size:11px}.review-fields input,.review-note{width:100%}.review-actions{display:flex;flex-wrap:wrap;gap:8px}.review-actions button{padding:9px 12px;font-size:12px}.review-note{min-height:55px;resize:vertical}.evidence{font-size:11px;color:#667970;margin-top:3px}.ai-summary{margin:12px 0;color:#40534c;line-height:1.5}
 </style><title>Shipping Document Verification</title>
<style>
:root{font-family:"Aptos","Segoe UI",sans-serif;color:#14231f;background:#eef3f0}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 85% 0,#dcefe7 0,transparent 34%),#eef3f0}.shell{max-width:1180px;margin:auto;padding:28px 22px 56px}.eyebrow{color:#087b68;font-weight:800;letter-spacing:.1em;text-transform:uppercase;font-size:11px}.head{display:flex;justify-content:space-between;gap:20px;align-items:end;margin-bottom:22px}.head h1{font-size:clamp(30px,4vw,48px);letter-spacing:-.03em;line-height:1;margin:7px 0 10px}.head p{color:#64736e;max-width:620px;margin:0;line-height:1.5}.panel{background:#fff;border:1px solid #d8e4de;border-radius:16px;padding:22px;box-shadow:0 12px 30px #1746380b;margin-bottom:16px}.form{display:grid;grid-template-columns:1fr 1fr;gap:14px}.wide{grid-column:1/-1}label{display:grid;gap:7px;font-weight:750;font-size:12px;color:#40534c}input,textarea{font:inherit;color:#162822;background:#fbfdfc;border:1px solid #cbdad3;border-radius:9px;padding:11px 12px;outline:none;transition:border-color .15s,box-shadow .15s}input:focus,textarea:focus{border-color:#15957b;box-shadow:0 0 0 3px #15957b1c}textarea{min-height:82px;resize:vertical}button{border:0;border-radius:9px;background:#087b68;color:white;font:inherit;font-weight:800;padding:11px 17px;cursor:pointer;transition:transform .15s,background .15s}button:hover{background:#066653;transform:translateY(-1px)}button:disabled{opacity:.6;cursor:wait;transform:none}button.secondary{background:#e5f2ed;color:#086650}.upload{border:1px dashed #b8cec4;border-radius:10px;padding:12px;background:#f7fbf9}.upload input{background:transparent;border:0;padding:0}.file-list{margin-top:8px;color:#50655d;font-size:12px;line-height:1.6}.status{display:flex;flex-wrap:wrap;gap:8px;margin:15px 0}.badge{border-radius:999px;padding:7px 10px;font-weight:850;font-size:11px;letter-spacing:.03em}.OK{background:#dff5e9;color:#147044}.MISMATCH{background:#ffe5df;color:#ad3d27}.NEEDS_REVIEW{background:#fff2c9;color:#8a6500}.summary{display:flex;justify-content:space-between;gap:18px;align-items:start}.summary h2{margin:5px 0 0;font-size:25px;letter-spacing:-.02em}.summary p{color:#60716a;line-height:1.5;margin:0 0 18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.card{border:1px solid #dce7e1;border-radius:11px;padding:15px;background:#fcfefd}.card h3{margin:0 0 10px;font-size:14px;color:#203a31}.field{display:grid;grid-template-columns:145px 1fr;gap:8px;padding:8px 0;border-bottom:1px solid #edf2ef;font-size:13px}.field:last-child{border:0}.diff{background:#fff8f5}.review{display:flex;align-items:center;justify-content:space-between;gap:14px;border:1px solid #f0dca2;background:#fffaf0;border-radius:11px;padding:13px 15px;margin-top:14px}.review h3{margin:0 0 3px;font-size:13px}.review p{margin:0;color:#7c6a3f;font-size:12px}.assistant{border-top:1px solid #e4ebe7;margin-top:22px;padding-top:20px}.assistant-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px}.assistant-head h3{margin:0;font-size:18px}.assistant-head span{font-size:11px;color:#7b8b84;background:#edf6f2;border-radius:999px;padding:5px 8px}.ask-row{display:flex;gap:9px}.ask-row input{flex:1}.answer{margin-top:12px;border:1px solid #cfe4db;border-left:3px solid #15957b;border-radius:10px;padding:14px 16px;color:#3d514a;line-height:1.55;background:#f8fcfa}.answer:empty{display:none}.answer p{margin:0 0 9px}.answer p:last-child{margin-bottom:0}.answer strong{color:#183f34}.answer ul{margin:7px 0 5px;padding-left:20px}.muted{color:#687a72}.error{color:#b42318;font-weight:700;white-space:pre-wrap;margin-top:12px}.hidden{display:none}hr{border:0;border-top:1px solid #e5ece8;margin:0}@media(max-width:700px){.shell{padding:20px 14px 40px}.head,.form,.grid{display:block}.panel{padding:16px;border-radius:13px;margin-bottom:12px}.form>*{margin-bottom:12px}.field{grid-template-columns:1fr;gap:3px}.summary{display:block}.review,.ask-row{display:block}.review button,.ask-row button{margin-top:10px;width:100%}.ask-row input{width:100%}}
</style></head><body><main class="shell">
<header class="head"><div><div class="eyebrow">Operations desk</div><h1>Shipping document verification</h1><p>Upload an email and its SI/BL attachments. The verifier extracts, compares, and highlights what needs attention.</p></div></header>
<section class="panel"><div class="queue-head"><div><div class="eyebrow">Case queue</div><h2>Recent verification cases</h2></div><div class="queue-tools"><select id="case-filter"><option value="ALL">All cases</option><option value="NEEDS_REVIEW">Needs review</option><option value="MISMATCH">Mismatch</option><option value="OK">OK</option><option value="UNPROCESSED">Unprocessed</option></select><button id="refresh-cases" class="secondary" type="button">Refresh</button><button id="process-inbox" type="button">Process inbox</button></div></div><div id="inbox-status" class="muted"></div><div id="case-list" class="case-list"><span class="muted">No cases loaded yet.</span></div></section>
<section class="panel"><form id="verify" class="form">
<label>Email ID<input name="email_id" required placeholder="email_new_001"></label>
<label>Sender<input name="sender" placeholder="docs@example.com"></label>
<label class="wide">Subject<input name="subject" required placeholder="TO CONFIRM DOCS"></label>
<label class="wide">Message<textarea name="body" placeholder="Please compare the SI and draft BL."></textarea></label>
<label class="wide upload">SI and BL attachments<div class="file-picker"><input id="attachments" name="attachments" type="file" multiple required accept=".txt,.pdf,.docx,.xlsx"><button id="add-files" type="button">Add files</button><small class="muted">Add both files at once or select more files later.</small></div><div id="file-list" class="file-list">No attachments selected</div></label>
<div class="wide"><button id="verify-button">Verify documents</button></div>
</form><div id="error" class="error"></div></section>
<section id="result" class="panel" hidden><div id="summary" class="summary"></div><div id="ai-summary" class="card" hidden></div><div id="documents" class="grid"></div><div id="correction" class="review" hidden><div><h3>Human review</h3><p>Edit extracted values, record the decision, and save an audit note.</p><div id="review-fields" class="review-fields"></div><textarea id="review-note" class="review-note" placeholder="Reviewer note or clarification request..."></textarea><div class="review-actions"><button id="save-review" type="button">Save correction</button><button id="confirm-mismatch" type="button" class="secondary">Confirm mismatch</button><button id="false-alarm" type="button" class="secondary">Mark false alarm</button><button id="request-clarification" type="button" class="secondary">Request clarification</button></div></div></div><div class="assistant"><div class="assistant-head"><h3>Ask the verification assistant</h3><span id="provider-label">AI analysis</span></div><div id="chat-thread" class="chat-thread"><div class="chat-empty">Ask a question about this shipment to begin.</div></div><div class="ask-row"><input id="chat-message" placeholder="Ask a follow-up question..."><button id="chat-send">Ask AI</button></div></div></section>
</main>
<script>
const form=document.querySelector('#verify'), result=document.querySelector('#result'), error=document.querySelector('#error'), fileInput=document.querySelector('#attachments'), fileList=document.querySelector('#file-list'), chatMessage=document.querySelector('#chat-message'), chatThread=document.querySelector('#chat-thread'), verifyButton=document.querySelector('#verify-button'), chatButton=document.querySelector('#chat-send'), addFiles=document.querySelector('#add-files'), caseList=document.querySelector('#case-list'), caseFilter=document.querySelector('#case-filter'), reviewFields=document.querySelector('#review-fields'), reviewNote=document.querySelector('#review-note'), processInboxButton=document.querySelector('#process-inbox'), inboxStatus=document.querySelector('#inbox-status');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formatAnswer=value=>esc(value).replace(/[*][*](.*?)[*][*]/g,'<strong>$1</strong>').replace(/^[-*] (.*)$/gm,'<li>$1</li>').replace(/(<li>.*<[/]li>)/gs,'<ul>$1</ul>').split(String.fromCharCode(10)+String.fromCharCode(10)).map(part=>part.trim()?`<p>${part.split(String.fromCharCode(10)).join('<br>')}</p>`:'').join('');
let selectedFiles=[];
let chatHistory=[];
addFiles.addEventListener('click',()=>fileInput.click());
fileInput.addEventListener('change',()=>{selectedFiles=[...selectedFiles,...fileInput.files];const unique=[];for(const file of selectedFiles){if(!unique.some(item=>item.name===file.name&&item.size===file.size))unique.push(file)}selectedFiles=unique;const transfer=new DataTransfer();selectedFiles.forEach(file=>transfer.items.add(file));fileInput.files=transfer.files;fileList.innerHTML=selectedFiles.length?selectedFiles.map(file=>`<span class="file-chip">${esc(file.name)}</span>`).join(''):'No attachments selected';});
function render(report){result.hidden=false;chatHistory=[];chatThread.innerHTML='<div class="chat-empty">Ask a question about this shipment to begin.</div>'; const status=report.status||'INFO'; const provider=report.ai_analysis?.provider||'AI'; document.querySelector('#provider-label').textContent=provider==='ollama'?'Qwen via Ollama':provider; document.querySelector('#summary').innerHTML=`<div class="eyebrow">${esc(report.email_id)} · ${esc(report.category)}</div><div class="status"><span class="badge ${esc(status)}">${esc(status)}</span>${report.review_reason?`<span class="badge NEEDS_REVIEW">${esc(report.review_reason)}</span>`:''}</div><p>${report.defect_fields?.length?`Fields needing attention: <strong>${report.defect_fields.map(esc).join(', ')}</strong>`:status==='OK'?'No mismatch detected.':report.message||''}</p>`; document.querySelector('#ai-summary').hidden=!report.ai_analysis?.text;document.querySelector('#ai-summary').innerHTML=report.ai_analysis?.text?`<strong>AI review summary</strong><div class="ai-summary">${formatAnswer(report.ai_analysis.text)}</div>`:''; const docs=report.documents||{}; document.querySelector('#documents').innerHTML=Object.entries(docs).map(([kind,doc])=>`<div class="card"><h3>${esc(kind.toUpperCase())}</h3>${Object.entries(doc.fields||{}).map(([k,v])=>`<div class="field"><strong>${esc(k)}</strong><span>${esc(v)}<div class="evidence">${esc(doc.confidence?.[k]||'')} · ${esc(doc.evidence?.[k]||'')}</div></span></div>`).join('')}</div>`).join(''); renderReviewFields(docs); document.querySelector('#correction').hidden=status!=='NEEDS_REVIEW'; window.current=report;loadCases();}
function renderReviewFields(docs){reviewFields.innerHTML=['si','bl'].map(kind=>`<div><strong>${kind.toUpperCase()}</strong>${Object.entries(docs[kind]?.fields||{}).map(([field,value])=>`<label>${esc(field)}<input data-document="${kind}" data-field="${field}" value="${esc(value)}"></label>`).join('')}</div>`).join('');}
async function loadCases(){try{const response=await fetch('/cases');const data=await response.json();const filter=caseFilter.value;caseList.innerHTML=data.cases.filter(item=>filter==='ALL'||item.status===filter).map(item=>`<div class="case-row"><button type="button" class="secondary" data-case="${esc(item.email_id)}">Open</button><strong>${esc(item.email_id)}</strong><span>${esc(item.status)}${item.review_reason?` · ${esc(item.review_reason)}`:''}</span><button type="button" class="secondary" data-retry="${esc(item.email_id)}">Retry</button></div>`).join('')||'<span class="muted">No matching cases.</span>';caseList.querySelectorAll('[data-case]').forEach(button=>button.addEventListener('click',()=>openCase(button.dataset.case)));caseList.querySelectorAll('[data-retry]').forEach(button=>button.addEventListener('click',()=>retryCase(button.dataset.retry)));}catch(error){caseList.innerHTML='<span class="error">Could not load cases.</span>';}}
async function processInbox(){processInboxButton.disabled=true;processInboxButton.textContent='Processing...';inboxStatus.textContent='Reading the configured inbox...';error.textContent='';try{const response=await fetch('/inbox/process',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({})});const data=await response.json();if(!response.ok)throw Error(data.detail||'Inbox processing failed');inboxStatus.textContent=`Processed ${data.processed} inbox email${data.processed===1?'':'s'}${data.failed?` · ${data.failed} failed`:''}.`;await loadCases();}catch(error){inboxStatus.textContent='Inbox processing failed.';document.querySelector('#error').textContent=error.message;}finally{processInboxButton.disabled=false;processInboxButton.textContent='Process inbox';}}
async function openCase(emailId){const response=await fetch('/cases/'+encodeURIComponent(emailId));const data=await response.json();if(!response.ok)throw Error(data.detail||'Could not open case');render(data.report);result.scrollIntoView({behavior:'smooth'});}
async function retryCase(emailId){try{const response=await fetch('/cases/'+encodeURIComponent(emailId)+'/retry',{method:'POST'});const data=await response.json();if(!response.ok)throw Error(data.detail||'Retry failed');render(data.report);}catch(error){document.querySelector('#error').textContent=error.message;}}
async function saveReview(decision){const r=window.current;if(!r)return;const correction={category:r.category,status:r.status,review_reason:r.review_reason,has_defect:r.has_defect||false,defect_fields:r.defect_fields||[],decision,note:reviewNote.value,si_fields:{},bl_fields:{}};document.querySelectorAll('#review-fields input').forEach(input=>{correction[input.dataset.document+'_fields'][input.dataset.field]=input.value});const response=await fetch('/reviews/'+encodeURIComponent(r.email_id),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(correction)});const data=await response.json();if(!response.ok)throw Error(data.detail||'Could not save review');render(data.result);if(data.clarification_draft){document.querySelector('#review-fields').insertAdjacentHTML('afterend',`<div class="card"><strong>Clarification draft</strong><p>To: ${esc(data.clarification_draft.to)}</p><p>Subject: ${esc(data.clarification_draft.subject)}</p><p>${esc(data.clarification_draft.body).split(String.fromCharCode(10)).join('<br>')}</p></div>`);}}
form.addEventListener('submit',async e=>{e.preventDefault();error.textContent='';verifyButton.disabled=true;verifyButton.textContent='Verifying...';const data=new FormData(form);try{const r=await fetch('/verify',{method:'POST',body:data});const j=await r.json();if(!r.ok)throw Error(j.detail||'Upload failed');render(j.report)}catch(x){error.textContent=x.message}finally{verifyButton.disabled=false;verifyButton.textContent='Verify documents'}});
document.querySelector('#save-review').addEventListener('click',()=>saveReview('accept').catch(error=>{document.querySelector('#error').textContent=error.message}));document.querySelector('#confirm-mismatch').addEventListener('click',()=>saveReview('confirm_mismatch').catch(error=>{document.querySelector('#error').textContent=error.message}));document.querySelector('#false-alarm').addEventListener('click',()=>saveReview('false_alarm').catch(error=>{document.querySelector('#error').textContent=error.message}));document.querySelector('#request-clarification').addEventListener('click',()=>saveReview('request_clarification').catch(error=>{document.querySelector('#error').textContent=error.message}));document.querySelector('#refresh-cases').addEventListener('click',loadCases);document.querySelector('#process-inbox').addEventListener('click',processInbox);caseFilter.addEventListener('change',loadCases);loadCases();
async function sendChat(){const r=window.current;const message=chatMessage.value.trim();if(!r||!message)return;chatMessage.value='';if(chatHistory.length===0)chatThread.innerHTML='';chatThread.insertAdjacentHTML('beforeend',`<div class="chat-message user">${esc(message)}</div>`);const pending=document.createElement('div');pending.className='chat-message assistant';pending.textContent='Thinking...';chatThread.appendChild(pending);chatThread.scrollTop=chatThread.scrollHeight;chatButton.disabled=true;chatButton.textContent='Thinking...';try{const response=await fetch('/chat/'+encodeURIComponent(r.email_id),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,history:chatHistory})});const data=await response.json();if(!response.ok)throw Error(data.detail||'AI request failed');pending.innerHTML=formatAnswer(data.answer);chatHistory.push({role:'user',content:message},{role:'assistant',content:data.answer});}catch(x){pending.textContent=x.message}finally{chatButton.disabled=false;chatButton.textContent='Ask AI';chatThread.scrollTop=chatThread.scrollHeight;chatMessage.focus();}}
chatButton.addEventListener('click',sendChat);chatMessage.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();sendChat();}});
</script></body></html>"""
    )